import{_ as e,c as l,o as r,a3 as n}from"./chunks/framework.BusRvirq.js";const f=JSON.parse('{"title":"과업 변경 요청서 (Change Request Form)","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/public/templates/07_CR_Form_template.html"}]]},"headers":[],"relativePath":"public/templates/07_CR_Form_template.md","filePath":"public/templates/07_CR_Form_template.md","lastUpdated":1790810085000}'),a={name:"public/templates/07_CR_Form_template.md"};function s(i,t,o,d,g,h){return r(),l("div",null,[...t[0]||(t[0]=[n('<h1 id="과업-변경-요청서-change-request-form" tabindex="-1">과업 변경 요청서 (Change Request Form) <a class="header-anchor" href="#과업-변경-요청서-change-request-form" aria-label="Permalink to “과업 변경 요청서 (Change Request Form)”">​</a></h1><p>본 양식은 확정된 과업 범위(Scope Freeze) 이후 발생하는 신규 기능 추가, 기존 사양 변경, 외부 연계 규격 수정 등에 대하여 객관적인 영향도 분석 및 공수·일정 조정을 투명하게 심의하기 위해 작성하는 표준 변경 통제 서식입니다.</p><hr><h3 id="_1-변경-요청-기본-정보" tabindex="-1">1. 변경 요청 기본 정보 <a class="header-anchor" href="#_1-변경-요청-기본-정보" aria-label="Permalink to “1. 변경 요청 기본 정보”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">내용</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>요청 번호 (CR-ID)</strong></td><td style="text-align:left;">CR-[연도]-[일련번호] (예: CR-2026-003)</td></tr><tr><td style="text-align:left;"><strong>프로젝트명</strong></td><td style="text-align:left;">[계약서상 사업명]</td></tr><tr><td style="text-align:left;"><strong>요청 일자</strong></td><td style="text-align:left;">202 년 월 일</td></tr><tr><td style="text-align:left;"><strong>요청 기관 / 부서</strong></td><td style="text-align:left;">[발주처 요청 부서명]</td></tr><tr><td style="text-align:left;"><strong>요청자</strong></td><td style="text-align:left;">직급: [ ] 성명: [ ] (연락처: )</td></tr><tr><td style="text-align:left;"><strong>접수자 (수행사)</strong></td><td style="text-align:left;">직급: [ ] 성명: [ ] (접수일: 202 . . .)</td></tr><tr><td style="text-align:left;"><strong>변경 유형</strong></td><td style="text-align:left;">[ ] 신규 기능 추가 / [ ] 기존 사양 변경 / [ ] 데이터/연계 변경 / [ ] 법·규제 대응</td></tr><tr><td style="text-align:left;"><strong>긴급도</strong></td><td style="text-align:left;">[ ] 긴급 (3일 이내 조치) / [ ] 일반 (정기 스프린트 반영) / [ ] 차기 고도화 권고</td></tr></tbody></table><hr><h3 id="_2-변경-요청-상세-내용" tabindex="-1">2. 변경 요청 상세 내용 <a class="header-anchor" href="#_2-변경-요청-상세-내용" aria-label="Permalink to “2. 변경 요청 상세 내용”">​</a></h3><ol><li><strong>변경 요청 배경 및 필요성</strong>: <ul><li>[현업 업무 프로세스 변경, 발주처 내부 규정 개정, 대외 기관 API 스펙 변경 등 변경이 불가피한 배경을 구체적으로 기술]</li></ul></li><li><strong>변경 전 현행 사양 (As-Is)</strong>: <ul><li>[현재 설계/구현된 사양 및 RTM 요구사항 ID 기술]</li></ul></li><li><strong>변경 후 희망 사양 (To-Be)</strong>: <ul><li>[새롭게 요구하는 화면 입력 항목, 비즈니스 처리 규칙, 출력 결과 등 구체적 기술]</li></ul></li></ol><hr><h3 id="_3-수행사-기술-영향도-및-소요-공수-분석-수행사-작성란" tabindex="-1">3. 수행사 기술 영향도 및 소요 공수 분석 (수행사 작성란) <a class="header-anchor" href="#_3-수행사-기술-영향도-및-소요-공수-분석-수행사-작성란" aria-label="Permalink to “3. 수행사 기술 영향도 및 소요 공수 분석 (수행사 작성란)”">​</a></h3><p>수행사의 기술 총괄(TL) 및 아키텍트는 접수일로부터 [ 3 ] 영업일 이내에 아래 영향도 분석을 완료하여 제출합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">분석 영역</th><th style="text-align:left;">영향받는 컴포넌트 및 세부 내역</th><th style="text-align:center;">정량 영향 수치</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>데이터베이스</strong></td><td style="text-align:left;">테이블 신규 생성: [ ] 개, 컬럼 추가/변경: [ ] 개, 인덱스 재구성</td><td style="text-align:center;">[ ] 개 테이블</td></tr><tr><td style="text-align:left;"><strong>백엔드 API</strong></td><td style="text-align:left;">Controller/Service 수정: [ ] 개, 신규 REST 엔드포인트: [ ] 개</td><td style="text-align:center;">[ ] 개 API</td></tr><tr><td style="text-align:left;"><strong>프론트엔드 UI</strong></td><td style="text-align:left;">수정 대상 화면: [ ] 개, 신규 팝업/모달: [ ] 개, 유효성 검증 로직</td><td style="text-align:center;">[ ] 개 화면</td></tr><tr><td style="text-align:left;"><strong>외부 연계</strong></td><td style="text-align:left;">대외 기관 전문 파싱 변경, 통신 프로토콜 암호화 변경</td><td style="text-align:center;">[ ] 건 연계</td></tr><tr><td style="text-align:left;"><strong>테스트 공수</strong></td><td style="text-align:left;">단위/통합 테스트 케이스 추가 및 회귀 테스트 공수</td><td style="text-align:center;">[ ] M/D</td></tr><tr><td style="text-align:left;"><strong>총 소요 공수</strong></td><td style="text-align:left;"><strong>분석, 설계, 개발, 단위검증, 배포를 포함한 총 투입 인력 공수</strong></td><td style="text-align:center;"><strong>총 [ ] M/D</strong></td></tr></tbody></table><ul><li><strong>프로젝트 납기(마일스톤) 영향</strong>: <ul><li>[ ] 기존 일정 내 흡수 가능 (단, 타 업무 우선순위 조정 필요)</li><li>[ ] 프로젝트 최종 완료일 [ ] 일 순연(연장) 필요</li><li>[ ] 별도 추가 예산(계약 변경) 필요 (소요 예상 비용: 일금 [ ] 원)</li></ul></li></ul><hr><h3 id="_4-변경-처리-방안-및-최종-합의" tabindex="-1">4. 변경 처리 방안 및 최종 합의 <a class="header-anchor" href="#_4-변경-처리-방안-및-최종-합의" aria-label="Permalink to “4. 변경 처리 방안 및 최종 합의”">​</a></h3><ul><li><p><strong>양사 PM 협의 결과</strong>:</p><ul><li>[ ] <strong>승인 (원안 수용)</strong>: 공수 및 일정 변경을 수용하고 개발 착수</li><li>[ ] <strong>승인 (조건부 절충)</strong>: 일정 연장 없이 타 기능(ID: [ ]) 개발을 제외/축소하여 공수 상쇄</li><li>[ ] <strong>보류 (차기 사업 이관)</strong>: 본 사업 범위에서 제외하고 향후 2차 고도화 사업으로 이관</li><li>[ ] <strong>반려 (기각)</strong>: 시스템 아키텍처 제약 및 납기 위험으로 인해 수용 불가</li></ul></li><li><p><strong>상세 합의 및 특약 사항</strong>: [ ]</p></li></ul><hr><p>위와 같이 과업 변경 요청에 대한 영향도 분석 및 처리 방안에 최종 합의합니다.</p><p><strong>합의일자: 202 년 월 일</strong></p><p><strong>[발주처 사업 책임자 (PM)]</strong></p><ul><li>소속: [ ]</li><li>직급: [ ] 성명: [ ] (서명)</li></ul><p><strong>[수행사 사업 책임자 (PM)]</strong></p><ul><li>소속: 주식회사 엠파시</li><li>직급: [ ] 성명: [ ] (서명)</li></ul>',23)])])}const _=e(a,[["render",s]]);export{f as __pageData,_ as default};
